def make_textbook_entry(content_dict, length="medium", ttype="unit_lesson", tags=None):
    return {
        "subject": content_dict["subject"],
        "topic": content_dict["topic"],
        "level": content_dict["level"],
        "length": length,
        "type": ttype,
        "title": content_dict["title"],
        "tags": tags or [],
        "content": content_dict,
        "status": "published",
        "source": "claude_max_seed_batch02",
    }


